def compute(vars):
    due_in_less_than_one_year = vars["v1"]
    total_long_term_debt = vars["v2"]

    if total_long_term_debt == 0:
        return None

    value = due_in_less_than_one_year / total_long_term_debt

    return {
        "value": value,
        "trace": {
            "due_in_less_than_one_year": due_in_less_than_one_year,
            "total_long_term_debt": total_long_term_debt,
            "ratio": value,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "ratio"
            }
        }
    }
